+/**
+ * Partition objects so all Frame objects are at the END of the array (highest z-order).
+ * Non-frame relative order and frame relative order are both preserved.
+ */
+export const ensureFramesOnTop = (objects: CanvasObject[]): CanvasObject[] => {
+  const nonFrames: CanvasObject[] = [];
+  const frames: CanvasObject[] = [];
+  for (const obj of objects) {
+    if (isFrameObject(obj)) {
+      frames.push(obj);
+    } else {
+      nonFrames.push(obj);
+    }
+  }
+  if (frames.length === 0) return objects;
+  return [...nonFrames, ...frames];
+};
